  @Test
  void sortTreeAndSummary() {
    Span root = span(T1, "a", null, "root", "front", 100);
    Span childB = span(T1, "c", "a", "child-b", "back", 120);
    Span childA = span(T1, "b", "a", "child-a", "back", 110);
    Span grand = span(T1, "d", "c", "grandchild", "back", 130);
    Span orphan = span(T1, "e", "ff", "orphan", "front", 90);
    Span self = span(T1, "f", "f", "self", "front", 200);
    Span cycle1 = span(T1, "11", "12", "cycle1", "front", 300);
    Span cycle2 = span(T1, "12", "11", "cycle2", "front", 301);
    Span dup = span(T1, "a", null, "dup", "front", 400);
    List<Span> all = List.of(grand, childB, root, childA, orphan, self, cycle1, cycle2, dup);
    assertThat(Traces.sortSpans(all))
        .extracting(Span::name)
        .startsWith("orphan", "root", "child-a", "child-b", "grandchild");
    List<SpanNode> tree = Traces.buildTree(all);
    assertThat(tree)
        .extracting(n -> n.span().name())
        .containsExactly("orphan", "root", "self", "dup", "cycle1");
    SpanNode r = tree.get(1);
    assertThat(r.children()).extracting(n -> n.span().name()).containsExactly("child-a", "child-b");
    assertThat(r.children().get(1).children())
        .extracting(n -> n.span().name())
        .containsExactly("grandchild");
    Trace trace = new Trace(T1, all);
    assertThat(trace.root()).map(Span::name).contains("orphan");
    assertThat(trace.spansNamed("child-a")).hasSize(1);
    TraceSummary sum = Traces.summarize(new Trace(T1, List.of(root, childA, childB, grand)));
    assertThat(sum.rootName()).contains("root");
    assertThat(sum.rootServiceName()).contains("front");
    assertThat(sum.startMicros()).isEqualTo(100);
    assertThat(sum.durationMicros()).isEqualTo(130);
    assertThat(sum.spanCount()).isEqualTo(4);
    TraceSummary empty = Traces.summarize(new Trace(T1, null));
    assertThat(empty.rootName()).isEmpty();
    assertThat(empty.durationMicros()).isZero();
    assertThat(new Trace(T1, List.of()).root()).isEmpty();
    TraceSummary nulls = new TraceSummary(T1, (Optional<String>) null, null, 0, 0, 0);
    assertThat(nulls.rootServiceName()).isEmpty();
    assertThat(new DependencyLink("a", "b", 2).callCount()).isEqualTo(2);
  }

