  @Test
  void jsonRoundTrip() {
    Span s =
        Span.builder(T1, "1", "op")
            .parentSpanId("2")
            .kind(Span.Kind.CLIENT)
            .serviceName("svc")
            .times(1_700_000_000_000_001L, 1_700_000_000_000_101L)
            .status(Span.StatusCode.ERROR, "bad")
            .attributes(
                Map.of("n", 1, "d", 1.5, "b", true, "l", List.of("x"), "m", Map.of("k", "v")))
            .event(new Span.Event("e", 1_700_000_000_000_050L, Map.of("k", 2)))
            .link(new Span.Link(T2, "3", Map.of()))
            .build();
    Trace t = new Trace(T1, List.of(s, span(T1, "4", null, "root", "svc", 0)));
    String json = TraceJson.toJson(t);
    assertThat(json)
        .contains("\"startMicros\":1700000000000001")
        .contains("\"status\":{\"code\":\"error\",\"message\":\"bad\"}")
        .contains("\"timeMicros\":1700000000000050");
    Trace back = TraceJson.traceFromJson(json);
    assertThat(TraceJson.toJson(back)).isEqualTo(json);
    assertThat(back.spans().get(1).attributes()).containsEntry("n", 1L);
    assertThat(TraceJson.toJson(TraceJson.spanFromJson(TraceJson.toJson(s))))
        .isEqualTo(TraceJson.toJson(s));
    Span lenient =
        TraceJson.spanFromJson(
            "{\"traceId\":\""
                + T1
                + "\",\"spanId\":\"5\",\"name\":\"n\",\"parentSpanId\":null,"
                + "\"startMicros\":10,\"endMicros\":30,\"status\":\"ok\",\"attributes\":{\"z\":null}}");
    assertThat(lenient.durationMicros()).isEqualTo(20);
    assertThat(lenient.status().code()).isEqualTo(Span.StatusCode.OK);
    assertThat(lenient.serviceName()).isEmpty();
    assertThat(lenient.attributes()).containsEntry("z", "");
    Span noStatus =
        TraceJson.spanFromJson(
            "{\"traceId\":\"" + T1 + "\",\"spanId\":\"5\",\"name\":\"n\",\"status\":null}");
    assertThat(noStatus.status()).isEqualTo(Span.Status.UNSET);
    Span codeOnly =
        TraceJson.spanFromJson(
            "{\"traceId\":\""
                + T1
                + "\",\"spanId\":\"5\",\"name\":\"n\",\"status\":{\"code\":\"ok\",\"message\":null}}");
    assertThat(codeOnly.status().message()).isEmpty();
    assertThatThrownBy(() -> TraceJson.spanFromJson("[]")).isInstanceOf(ValidationException.class);
    assertThatThrownBy(() -> TraceJson.spanFromJson("{")).isInstanceOf(ValidationException.class);
    assertThat(TraceJson.timestamp(1_000_001L)).isEqualTo("1970-01-01T00:00:01.000001Z");
    assertThat(TraceJson.timestamp(-1L)).isEqualTo("1969-12-31T23:59:59.999999Z");
    assertThat(TraceJson.micros("1970-01-01T00:00:01.000001Z")).isEqualTo(1_000_001L);
    assertThatThrownBy(() -> TraceJson.micros("x")).isInstanceOf(ValidationException.class);
    assertThatThrownBy(() -> TraceJson.micros(null)).isInstanceOf(ValidationException.class);
  }

  @Test
  void queryClientDefaults() throws Exception {
    AtomicInteger calls = new AtomicInteger();
    TraceQueryClient client =
        new TraceQueryClient() {
          @Override
          public Optional<Trace> getTrace(String traceId) {
            int n = calls.incrementAndGet();
            if (n == 1) {
              throw new UnavailableException("indexing");
            }
            List<Span> spans = new ArrayList<>();
            spans.add(span(T1, "1", null, "root", "svc", 0));
            if (n >= 3) {
              spans.add(span(T1, "2", "1", "child", "svc", 1));
            }
            return Optional.of(new Trace(traceId, spans));
          }

          @Override
          public List<TraceSummary> searchTraces(TraceSearchQuery query) {
            return List.of();
          }

          @Override
          public List<String> listServices() {
            return List.of("svc");
          }

          @Override
          public List<String> listOperations(String service) {
            return List.of("root");
          }
        };
    Trace t =
        client.waitForTrace(
            T1.toUpperCase(),
            new WaitForTraceOptions(Duration.ofSeconds(5), Duration.ofMillis(5), 2));
    assertThat(t.spans()).hasSize(2);
    assertThat(client.waitForTrace(T1).spans()).hasSize(2);
    assertThatThrownBy(() -> client.getDependencies(null, null))
        .isInstanceOf(UnsupportedException.class);
    assertThat(client.getTraceAsync(T1).get(5, TimeUnit.SECONDS)).isPresent();
    assertThat(
            client.searchTracesAsync(TraceSearchQuery.builder().build()).get(5, TimeUnit.SECONDS))
        .isEmpty();
    assertThat(client.listServicesAsync().get(5, TimeUnit.SECONDS)).containsExactly("svc");
    assertThat(client.listOperationsAsync("svc").get(5, TimeUnit.SECONDS)).containsExactly("root");
    assertThatThrownBy(() -> client.getDependenciesAsync(null, null).join())
        .hasCauseInstanceOf(UnsupportedException.class);
    assertThat(
            client
                .waitForTraceAsync(T1, WaitForTraceOptions.defaults())
                .get(5, TimeUnit.SECONDS)
                .spans())
        .hasSize(2);
    InMemoryTraceQueryClient empty = new InMemoryTraceQueryClient(List::of);
    assertThatThrownBy(
            () ->
                empty.waitForTrace(
                    T1, new WaitForTraceOptions(Duration.ofMillis(30), Duration.ofMillis(5), 1)))
        .isInstanceOf(TimeoutException.class);
    assertThat(WaitForTraceOptions.defaults().timeout()).hasSeconds(30);
  }

  @Test
  void inMemoryQueryClient() {
    List<Span> spans =
        List.of(
            span(T1, "1", null, "GET /", "front", 1000),
            Span.builder(T1, "2", "SELECT")
                .parentSpanId("1")
                .serviceName("db")
                .times(1010, 1050)
                .attribute("db.system", "pg")
                .build(),
            span(T1, "3", "1", "render", "front", 1060),
            span(T2, "4", null, "job", "worker", 5000),
            span(T2, "5", "4", "SELECT", "db", 5001));
    InMemoryTraceQueryClient q = new InMemoryTraceQueryClient(() -> spans);
    assertThat(q.getTrace(T1)).map(t -> t.spans().size()).contains(3);
    assertThat(q.getTrace("1234")).isEmpty();
    assertThat(q.listServices()).containsExactly("db", "front", "worker");
    assertThat(q.listOperations("db")).containsExactly("SELECT");
    assertThat(q.searchTraces(TraceSearchQuery.builder().build()))
        .extracting(TraceSummary::traceId)
        .containsExactly(T2, T1);
    assertThat(q.searchTraces(TraceSearchQuery.builder().limit(1).build())).hasSize(1);
    assertThat(q.searchTraces(TraceSearchQuery.forService("front"))).hasSize(1);
    assertThat(q.searchTraces(TraceSearchQuery.builder().service("db").operation("SELECT").build()))
        .hasSize(2);
    assertThat(
            q.searchTraces(TraceSearchQuery.builder().service("front").operation("SELECT").build()))
        .isEmpty();
    assertThat(q.searchTraces(TraceSearchQuery.builder().tag("db.system", "pg").build()))
        .hasSize(1);
    assertThat(q.searchTraces(TraceSearchQuery.builder().tag("db.system", "mysql").build()))
        .isEmpty();
    assertThat(q.searchTraces(TraceSearchQuery.builder().minDurationMicros(1000L).build()))
        .isEmpty();
    assertThat(q.getDependencies(null, null))
        .containsExactly(
            new DependencyLink("front", "db", 1), new DependencyLink("worker", "db", 1));
    Instant at4000 = Instant.ofEpochSecond(0, 4_000_000L);
    assertThat(q.getDependencies(at4000, null))
        .containsExactly(new DependencyLink("worker", "db", 1));
    assertThat(q.getDependencies(null, at4000))
        .containsExactly(new DependencyLink("front", "db", 1));
  }
